/**
 * Blog seed content catalog — editorial definitions for SHARED and country-specific articles.
 * Consumed by the blog seed script via buildArticleBody and buildArabicDraft.
 */

export const BLOG_SEED_VERSION = 'blog-seo-content-v1'

/** @typedef {import('./buildArticleBody.mjs').SectionDef} SectionDef */

/**
 * @typedef {Object} FaqDef
 * @property {string} [id]
 * @property {string} question
 * @property {string} questionAr
 * @property {string} answer
 * @property {string} answerAr
 */

/**
 * @typedef {Object} ArticleDef
 * @property {string} id
 * @property {string} slug
 * @property {string|null} countryCode
 * @property {string} categoryId
 * @property {string} featuredImage
 * @property {string[]} tags
 * @property {string} primaryKeyword
 * @property {string} [primaryKeywordAr]
 * @property {string} searchIntent
 * @property {string} seoTitle
 * @property {string} seoTitleAr
 * @property {string} seoDescription
 * @property {string} seoDescriptionAr
 * @property {string} title
 * @property {string} titleAr
 * @property {string} excerpt
 * @property {string} excerptAr
 * @property {string} featuredImageAlt
 * @property {string} featuredImageAltAr
 * @property {SectionDef[]} sections
 * @property {FaqDef[]} faq
 * @property {string[]} [relatedSlugs]
 * @property {string} [relatedSolutionUrl]
 * @property {string} [ctaHeading]
 * @property {string} [ctaHeadingAr]
 * @property {string} [ctaDescription]
 * @property {string} [ctaDescriptionAr]
 * @property {boolean} [featured]
 * @property {boolean} [showOnHomepage]
 * @property {number} [sortOrder]
 * @property {string} [_seedVersion]
 */

/** Attach seed version and optional section expansions. */
function article(def) {
  const extra = SECTION_EXPANSIONS[def.slug] || []
  const extra2 = SECOND_SECTION_EXPANSIONS[def.slug] || []
  const extra3 = THIRD_SECTION_EXPANSIONS[def.slug] || []
  const sections = [...def.sections, ...extra, ...extra2, ...extra3]
  return { ...def, sections, _seedVersion: BLOG_SEED_VERSION }
}

