    slug: 'warehouse-picking-fulfillment-basics',
    countryCode: null,
    categoryId: 'cat-inventory',
    featuredImage: '/software-images/logistics-transportation-software/dashboard.jpg',
    tags: ['warehouse', 'fulfillment', 'logistics'],
    primaryKeyword: 'warehouse picking fulfillment',
